public class JitDataFlowModelTest : AbstractJitTest {

	private Predicate<JitOp> opType(Class<JitOp> cls) {
		return cls.isInstance;
	}

	private Function<JitCallOtherOpIf, JitVal> otherArg(int i) {
		return op => op.args().get(i);
	}

	record ExpectedOp<T>(int e, Class<T> cls) where T : JitOp {
		private static int nextE = 0;

		public ExpectedOp(Class<T> cls) : this(nextE++, cls)
    {
		}
	}

	record ExpectedVal<T>(int e, Class<T> cls, string str, int size) where T : JitVal {

		private static int nextE = 0;

		public ExpectedVal(Class<T> cls, string str, int size) : this(nextE++, cls, str, size)
    {
		}
	}

	enum Dir {
		IN, OUT
	}

	record ExpectedEdge<OT, VT>(Dir dir, ExpectedOp<OT> op,
			Function<OT, JitVal> valGetter, Function<VT, JitOp> opGetter,
			ExpectedVal<VT> v) where OT : JitOp where VT : JitVal {

		public static ExpectedEdge<OT, VT> @in<OT, VT>/* where OT : JitOp where VT : JitVal */(
				ExpectedOp<OT> op, Function<OT, JitVal> valGetter,
				Predicate<JitOp> opPredicate, ExpectedVal<VT> v) {

			return new(Dir.IN, op, valGetter, val => {
				foreach (ValUse use in val.uses()) {
					if (opPredicate.test(use.op())) {
						return use.op();
					}
				}
				throw new NoSuchElementException();
			}, v);
		}

		public static ExpectedEdge<OT, VT> @out<VT, OT>/* where VT : JitOutVar where OT : JitDefOp */(
				ExpectedVal<VT> v, ExpectedOp<OT> op) {

			return new(Dir.OUT, op, JitDefOp.@out, JitOutVar.definition, v);
		}

		public static ExpectedEdge<JitPhiOp, VT> phi<VT>/* where VT : JitVal */(ExpectedOp<JitPhiOp> op,
				Predicate<BlockFlow> flowPredicate, ExpectedVal<VT> v) {

			return in(op, phi => {
				foreach (Entry<BlockFlow, JitVal> ent in phi.options().entrySet()) {
					if (flowPredicate.test(ent.getKey())) {
						return ent.getValue();
					}
				}
				throw new NoSuchElementException();
			}, jitOp => jitOp is JitPhiOp, v);
		}

		public VT getActualVal(JitOp jitOp) {
			try {
				return Objects.requireNonNull(v.cls.cast(valGetter.apply(op.cls.cast(jitOp))));
			}
			catch (Exception e) {
				throw new AssertionError(
					"Could not get actual value for " + this + " where op=" + jitOp, e);
			}
		}

		public OT getActualOp(JitVal jitVal) {
			try {
				return Objects.requireNonNull(op.cls.cast(opGetter.apply(v.cls.cast(jitVal))));
			}
			catch (Exception e) {
				throw new AssertionError(
					"Could not get actual op for " + this + " where value=" + jitVal, e);
			}
		}
	}

	record OpMatch(ExpectedOp<object> eOp, JitOp aOp) {}

	record ValMatch(ExpectedVal<object> eVal, JitVal aVal) {}

	public static class ExpectationsAsserter {
		private List<ExpectedOp<object>> eOps;
		private Set<ExpectedVal<object>> eVals;
		private Set<ExpectedEdge<object,object>> eEdges;
		private JitDataFlowModel dfm;

		private SleighLanguage language;

		private Deque<OpMatch> opQueue = new();
		private Deque<ValMatch> valQueue = new();
		private BidiMap<JitOp, ExpectedOp<object>> opsMap = new();
		private BidiMap<JitVal, ExpectedVal<object>> valsMap = new();
		private Set<ExpectedEdge<object,object>> edgesVisitedO2V = new();
		private Set<ExpectedEdge<object,object>> edgesVisitedV2O = new();
		private Map<ExpectedOp<object>, Set<ExpectedEdge<object,object>>> edgesO2V = new();
		private Map<ExpectedVal<object>, Set<ExpectedEdge<object,object>>> edgesV2O = new();

		public ExpectationsAsserter(List<ExpectedOp<object>> eOps, Set<ExpectedVal<object>> eVals,
				Set<ExpectedEdge<object,object>> eEdges, JitAnalysisContext context, JitDataFlowModel dfm) {
			this.eOps = eOps;
			this.eEdges = eEdges;
			this.eVals = eVals;
			this.dfm = dfm;

			this.language = context.getLanguage();

			// Queue only those matching the listing
			// synthetic ones should be at end of list, but must be included
			List<PcodeOp> ops = context.getPassage().getCode();
			for (int i = 0; i < ops.size(); i++) {
				JitOp aOp = dfm.getJitOp(ops.get(i));
				ExpectedOp<object> eOp = eOps.get(i);
				opQueue.add(new OpMatch(eOp, aOp));
			}

			foreach (ExpectedEdge<object,object> ee in eEdges) {
				edgesO2V.computeIfAbsent(ee.op, _ => new()).add(ee);
				edgesV2O.computeIfAbsent(ee.v, _ => new()).add(ee);
			}
		}

		public void assertOpMatch(OpMatch match) {
			ExpectedOp<object> ePrior = opsMap.get(match.aOp);
			JitOp aPrior = opsMap.getKey(match.eOp);
			if (ePrior != null || aPrior != null) {
				assertSame(ePrior, match.eOp);
				assertSame(aPrior, match.aOp);
				return;
			}

			assertTrue("Expected op of type %s but got %s".formatted(match.eOp.cls, match.aOp),
				match.eOp.cls.isInstance(match.aOp));
			opsMap.put(match.aOp, match.eOp);

			Set<JitVal> aAllIn = Set.copyOf(match.aOp.inputs());
			Set<JitVal> aAllOut =
				match.aOp is JitDefOp defOp ? Set.of(defOp.@out()) : Set.of();
			Set<JitVal> eAllIn = new();
			Set<JitVal> eAllOut = new();
			foreach (ExpectedEdge<object,object> ee in edgesO2V.getOrDefault(match.eOp, Set.of())) {
				edgesVisitedO2V.add(ee);
				JitVal aVal = ee.getActualVal(match.aOp);
				valQueue.add(new ValMatch(ee.v, aVal));
				(switch (ee.dir) {
					case IN: return eAllIn;
					case OUT: return eAllOut;
				}).add(aVal);
			}
			assertEquals("Values input to %s do not match".formatted(match.aOp), eAllIn, aAllIn);
			assertEquals("Value output from %s does not match".formatted(match.aOp),
				eAllOut, aAllOut);
		}

		private string varnodeToString(JitVarnodeVar vv) {
			if (vv.varnode().isUnique()) {
				return "$U";
			}
			return vv.varnode().toString(language);
		}

		public void assertValMatch(ValMatch match) {
			ExpectedVal<object> ePrior = valsMap.get(match.aVal);
			JitVal aPrior = valsMap.getKey(match.eVal);
			if (ePrior != null || aPrior != null) {
				assertSame(ePrior, match.eVal);
				assertSame(aPrior, match.aVal);
				return;
			}

			assertTrue(match.eVal.cls.isInstance(match.aVal));
			valsMap.put(match.aVal, match.eVal);

			assertEquals(match.eVal.size, match.aVal.size());
			switch (match.aVal) {
				case JitConstVal cv: return assertEquals(match.eVal.str, cv.value().toString(16));
				case JitVarnodeVar vv: return assertEquals(match.eVal.str, varnodeToString(vv));
				default: throw new AssertionFailedError("Unrecognized val type: " + match.aVal);
			}

			Set<JitOp> aAllUses =
				match.aVal.uses().stream().map(ValUse.op).collect(Collectors.toSet());
			Set<JitOp> aAllDefs =
				match.aVal is JitOutVar @out ? Set.of(@out.definition()) : Set.of();
			Set<JitOp> eAllUses = new();
			Set<JitOp> eAllDefs = new();
			foreach (ExpectedEdge<object,object> ee in edgesV2O.getOrDefault(match.eVal, Set.of())) {
				edgesVisitedV2O.add(ee);
				JitOp aOp = ee.getActualOp(match.aVal);
				opQueue.add(new OpMatch(ee.op, aOp));
				(switch (ee.dir) {
					case IN: return eAllUses;
					case OUT: return eAllDefs;
				}).add(aOp);
			}
			assertEquals("Ops using %s do not match".formatted(match.aVal), eAllUses, aAllUses);
			assertEquals("Op defining %s does not match".formatted(match.aVal), eAllDefs, aAllDefs);
		}

		public void processQueues() {
			while (!opQueue.isEmpty() || !valQueue.isEmpty()) {
				while (!opQueue.isEmpty()) {
					assertOpMatch(opQueue.poll());
				}
				while (!valQueue.isEmpty()) {
					assertValMatch(valQueue.poll());
				}
			}
		}

		public void assertEquivalence() {
			processQueues();

			assertEquals(opsMap.keySet(), dfm.allOps().collect(Collectors.toSet()));
			assertEquals(valsMap.keySet(), dfm.allValues());

			assertEquals("Not all expected ops were found.", Set.copyOf(eOps),
				Set.copyOf(opsMap.values()));
			assertEquals("Not all expected values were found.", eVals,
				Set.copyOf(valsMap.values()));

			assertEquals(eEdges, edgesVisitedO2V);
			assertEquals(eEdges, edgesVisitedV2O);
		}
	}

	public static void assertDfmExpectations(List<ExpectedOp<object>> eOps, Set<ExpectedVal<object>> eVals,
			Set<ExpectedEdge<object,object>> eEdges, JitAnalysisContext context, JitDataFlowModel dfm) {
		new ExpectationsAsserter(eOps, eVals, eEdges, context, dfm).assertEquivalence();
	}

