	/* @Test */
	public void testForLoop()
    {
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();

		// Want to see r0 as input or as previous iteration's value
		PcodeProgram program = SleighProgramCompiler.compileProgram(language, "test", """
				<loop>
				r0 = r0 - 1;
				if r0 > 0 goto <loop>;
				goto 0x1234;
				""", PcodeUseropLibrary.NIL);
		JitAnalysisContext context = makeContext(program);
		JitControlFlowModel cfm = new JitControlFlowModel(context);
		JitDataFlowModel dfm = new JitDataFlowModel(context, cfm);

		ExpectedOp<JitPhiOp> ePhi = new(typeof(JitPhiOp));
		ExpectedOp<JitIntSubOp> eIntSub = new(typeof(JitIntSubOp));
		ExpectedOp<JitIntLessOp> eIntLess = new(typeof(JitIntLessOp));
		ExpectedOp<JitCBranchOp> eCBranch = new(typeof(JitCBranchOp));
		ExpectedOp<JitBranchOp> eBranch = new(typeof(JitBranchOp));
		ExpectedVal<JitConstVal> e1 = new(typeof(JitConstVal), "1", 8);
		ExpectedVal<JitOutVar> eR0_1 = new(typeof(JitOutVar), "r0", 8);
		ExpectedVal<JitInputVar> eR0In = new(typeof(JitInputVar), "r0", 8);
		ExpectedVal<JitOutVar> eU = new(typeof(JitOutVar), "$U", 1);
		ExpectedVal<JitOutVar> eR0_2 = new(typeof(JitOutVar), "r0", 8);
		ExpectedVal<JitConstVal> e0 = new(typeof(JitConstVal), "0", 8);
		assertDfmExpectations(
			List.of(
				eIntSub,
				eIntLess,
				eCBranch,
				eBranch,
				ePhi),
			Set.of(e1, eR0_1, eR0In, eU, eR0_2, e0),
			Set.of(
				ExpectedEdge.phi(ePhi, flow => flow.from() == null, eR0In),
				ExpectedEdge.phi(ePhi, flow => flow.from() != null, eR0_2),
				ExpectedEdge.@out(eR0_1, ePhi),
				ExpectedEdge.in(eIntSub, JitIntSubOp.l, opType(typeof(JitIntSubOp)), eR0_1),
				ExpectedEdge.in(eIntSub, JitIntSubOp.r, opType(typeof(JitIntSubOp)), e1),
				ExpectedEdge.@out(eR0_2, eIntSub),
				ExpectedEdge.in(eIntLess, JitIntLessOp.l, opType(typeof(JitIntLessOp)), e0),
				ExpectedEdge.in(eIntLess, JitIntLessOp.r, opType(typeof(JitIntLessOp)), eR0_2),
				ExpectedEdge.@out(eU, eIntLess),
				ExpectedEdge.in(eCBranch, JitCBranchOp.cond, opType(typeof(JitCBranchOp)), eU)),
			context, dfm);
	}

