	/* @Test */
	public void testConstantFoldingRewriteConstInput()
    {
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();

		JitAnalysisContext context = makeContext(language, """
				r1 = 0x10;
				r0 = r0 + r1;
				goto 0x1234;
				""", MY_LIB);
		JitControlFlowModel cfm = new JitControlFlowModel(context);
		JitDataFlowModel dfm = new JitDataFlowModel(context, cfm);

		ExpectedOp<JitCopyOp> eCopy = new(typeof(JitCopyOp));
		ExpectedOp<JitIntAddOp> eAdd = new(typeof(JitIntAddOp));
		ExpectedOp<JitBranchOp> eBranch = new(typeof(JitBranchOp));
		ExpectedOp<JitPhiOp> ePhi = new(typeof(JitPhiOp));
		ExpectedVal<JitConstVal> e10_1 = new(typeof(JitConstVal), "10", 8);
		// Not great, but each getVar(const) has its own instance
		ExpectedVal<JitConstVal> e10_2 = new(typeof(JitConstVal), "10", 8);
		ExpectedVal<JitOutVar> eR1 = new(typeof(JitOutVar), "r1", 8);
		ExpectedVal<JitInputVar> eR0In = new(typeof(JitInputVar), "r0", 8);
		ExpectedVal<JitOutVar> eR0_1 = new(typeof(JitOutVar), "r0", 8);
		ExpectedVal<JitOutVar> eR0_2 = new(typeof(JitOutVar), "r0", 8);
		assertDfmExpectations(
			List.of(
				eCopy,
				eAdd,
				eBranch,
				ePhi),
			Set.of(e10_1, e10_2, eR1, eR0In, eR0_1, eR0_2),
			Set.of(
				ExpectedEdge.in(eCopy, JitCopyOp.u, opType(typeof(JitCopyOp)), e10_1),
				ExpectedEdge.@out(eR1, eCopy),
				ExpectedEdge.phi(ePhi, flow => flow.from() == null, eR0In),
				ExpectedEdge.@out(eR0_1, ePhi),
				ExpectedEdge.in(eAdd, JitIntAddOp.l, opType(typeof(JitIntAddOp)), eR0_1),
				ExpectedEdge.in(eAdd, JitIntAddOp.r, opType(typeof(JitIntAddOp)), e10_2), // <--
				ExpectedEdge.@out(eR0_2, eAdd)),
			context, dfm);
	}

	/* @Test */
	public void testConstantFoldingDontRewriteConstInputInterveningCallOther()
    {
		/**
		 * A non-functional userop could technically do whatever to the state, so nothing can be
		 * assumed constant after such a userop.
		 */
		SleighLanguage language = SleighLanguageHelper.getMockBE64Language();

		JitAnalysisContext context = makeContext(language, """
				r1 = 0x10;
				opaque();
				r0 = r0 + r1;
				goto 0x1234;
				""", MY_LIB);
		JitControlFlowModel cfm = new JitControlFlowModel(context);
		JitDataFlowModel dfm = new JitDataFlowModel(context, cfm);

		ExpectedOp<JitCopyOp> eCopy = new(typeof(JitCopyOp));
		ExpectedOp<JitCallOtherOp> eCallOther = new(typeof(JitCallOtherOp));
		ExpectedOp<JitIntAddOp> eAdd = new(typeof(JitIntAddOp));
		ExpectedOp<JitBranchOp> eBranch = new(typeof(JitBranchOp));
		ExpectedOp<JitPhiOp> ePhi = new(typeof(JitPhiOp));
		ExpectedVal<JitConstVal> e10_1 = new(typeof(JitConstVal), "10", 8);
		ExpectedVal<JitOutVar> eR1 = new(typeof(JitOutVar), "r1", 8);
		ExpectedVal<JitInputVar> eR0In = new(typeof(JitInputVar), "r0", 8);
		ExpectedVal<JitOutVar> eR0_1 = new(typeof(JitOutVar), "r0", 8);
		ExpectedVal<JitOutVar> eR0_2 = new(typeof(JitOutVar), "r0", 8);
		assertDfmExpectations(
			List.of(
				eCopy,
				eCallOther,
				eAdd,
				eBranch,
				ePhi),
			Set.of(e10_1, eR1, eR0In, eR0_1, eR0_2),
			Set.of(
				ExpectedEdge.in(eCopy, JitCopyOp.u, opType(typeof(JitCopyOp)), e10_1),
				ExpectedEdge.@out(eR1, eCopy),
				ExpectedEdge.phi(ePhi, flow => flow.from() == null, eR0In),
				ExpectedEdge.@out(eR0_1, ePhi),
				ExpectedEdge.in(eAdd, JitIntAddOp.l, opType(typeof(JitIntAddOp)), eR0_1),
				ExpectedEdge.in(eAdd, JitIntAddOp.r, opType(typeof(JitIntAddOp)), eR1), // <--
				ExpectedEdge.@out(eR0_2, eAdd)),
			context, dfm);
	}

	/**
	 * NOTE: cat, subpiece, etc., do not currently have much meaning except to indicate a
	 * dependence. At one point these "synthetic" ops were meant to be translated into JVM bytecode,
	 * but instead, variable accesses are coalesced during allocation/assignment, and then
	 * sub-accesses are encoded as such.
	 */
}
